    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
def arrows(g):
    H,W=len(g),len(g[0]); out=[]
    for i in range(H):
        for j in range(W-2):
            if g[i][j]==2 and g[i][j+1]==2 and g[i][j+2]==2:
                for r in (-1,1):
                    tt=(i+r,j+1)
                    if 0<=tt[0]<H and g[tt[0]][tt[1]]==2:
                        out.append((tt,(i,j),'UP' if tt[0]<i else 'DOWN'))
    return out
SU=[(0,0),(0,2),(2,0),(2,2)]
SD=[(0,3),(0,5),(2,3),(2,5)]
for n in range(1,8):
    g=G[f'Demo pair {n} input']; o=G[f'Demo pair {n} output']
    ar=arrows(g); H,W=len(g),len(g[0])
    dots=[(i,j,o[i][j]) for i in range(3) for j in range(6) if o[i][j]]
    pU=set(); pD=set()
    sorted_ar=sorted(ar,key=lambda p:p[1])
    for k,p in enumerate(sorted_ar):
        t,b,oop=p
        sl = SU if oop=='UP' else SD
        s=sl[min(k,len(sl)-1)]
        c=3 if oop=='UP' else 1
        if oop=='UP': pU.add(s)
        else: pD.add(s)
    aU=[c for i,j,c in dots if c==3]; aD=[c for i,j,c in dots if c==1]
    print('demo',n,'U pred:',sorted(pU),'U act:',aU)
    print('        D pred:',sorted(pD),'D act:',aD)

