    for i in range(H):
        for j in range(W-2):
            if g[i][j] and g[i][j+1] and g[i][j+2]:
                if i>0 and g[i-1][j+1]: out.append(('U',i,j,(i-1,j+1)))
                elif i+1<H and g[i+1][j+1]: out.append(('D',i,j,(i+1,j+1)))
    return out
for n,g,o in demos:
    H,W=len(g),len(g[0])
    ar=tips(g)
    upts=[(a,i,j,t) for a,i,j,t in ar if a=='U']; dp=[(a,i,j,t) for a,i,j,t in ar if a=='D']
    threes=[p for p in [(ii,jj) for ii in range(3) for jj in range(6) if o[ii][jj]==3]]
    ones=[p for p in [(ii,jj) for ii in range(3) for jj in range(6) if o[ii][jj]==1]]
    def cost(p,t): return abs(t[0]/H - p[0]/3) + abs(t[1]/W - p[1]/5)
    best=None
    for pm_u in itertools.permutations(threes,len(upts)):
        for pm_d in itertools.permutations(ones,len(dp)):
            sc=sum(cost(p,t) for p,t in zip(pm_u,upts))+sum(cost(p,t) for p,t in zip(pm_d,dp))
            if best is None or sc<best[0]: best=(sc,pm_u,pm_d)
    print('=== demo',n,'cost',round(best[0],4),'H,W=',H,W)
    for idx,p in enumerate(zip(best[1],upts)):
        print('  U tip',p[1][3],'slot',p[0])
    for idx,p in enumerate(zip(best[2],dp)):
        print('  D tip',p[1][3],'slot',p[0])

